buy_code:
매수 = True
if 데이터길이 < {min_len}:
    매수 = False
elif {b1_start} <= 시분초 < {b1_end}:
    if not ({b1_cap_lo} <= 시가총액 < {b1_cap_hi}):
        매수 = False
    elif not (등락율 >= {b1_rate_min} and 등락율 <= {b1_rate_max} and 분당거래대금 >= {b1_min_money} and 분당거래대금 >= 분당거래대금평균({b1_money_win}, 1) * {b1_money_mult} and 분당매수수량 >= {b1_buy_qty_min} and 누적분당매수수량({b1_cum_win}) >= 분당매수수량 * {b1_cum_vs_now}):
        매수 = False
elif {b2_start} <= 시분초 < {b2_end}:
    if not ({b2_cap_lo} <= 시가총액 < {b2_cap_hi}):
        매수 = False
    elif not (등락율 >= {b2_rate_min} and 등락율 <= {b2_rate_max} and 분당거래대금 >= {b2_min_money} and 분당거래대금 >= 분당거래대금평균({b2_money_win}, 1) * {b2_money_mult} and 현재가 >= 이동평균({b2_price_win}, 1) * {b2_price_reclaim_mult} and 분당매수수량 >= {b2_buy_qty_min} and 누적분당매수수량({b2_cum_win}) >= 분당매수수량 * {b2_cum_vs_now}):
        매수 = False
else:
    매수 = False
if 매수:
    self.Buy()

sell_code:
if 수익률 >= {take_profit}:
    self.Sell()
elif 수익률 <= -{stop_loss}:
    self.Sell()
elif 최고수익률 >= {trail_start} and 수익률 <= 최고수익률 - {trail_gap}:
    self.Sell()
elif 보유시간 >= {max_hold}:
    self.Sell()
